import{c as e,Q as i,j as a,m as s}from"./chunks/framework.BPKcPtvA.js";const p=JSON.parse('{"title":"Rate limiting","description":"How GateKeeper limits login attempts, OTP requests, and password resets.","frontmatter":{"title":"Rate limiting","description":"How GateKeeper limits login attempts, OTP requests, and password resets."},"headers":[],"relativePath":"src/content/docs/security/rate-limiting.md","filePath":"src/content/docs/security/rate-limiting.md"}'),r={name:"src/content/docs/security/rate-limiting.md"};function n(o,t,d,l,h,c){return i(),a("div",null,[...t[0]||(t[0]=[s('<p>GateKeeper applies rate limits at several points in the authentication flow to slow down automated attacks.</p><h2 id="login-ip-based-limit" tabindex="-1">Login - IP-based limit <a class="header-anchor" href="#login-ip-based-limit" aria-label="Permalink to &quot;Login - IP-based limit&quot;">​</a></h2><p>The login endpoint (<code>POST /login</code>) tracks failed attempts per client IP address.</p><table tabindex="0"><thead><tr><th>Limit</th><th>Window</th><th>Action on breach</th></tr></thead><tbody><tr><td>20 failed attempts</td><td>15 minutes</td><td>All further attempts from that IP return an error until the window resets</td></tr></tbody></table><p>The counter increments on every response that would have said &quot;Invalid credentials&quot; - wrong password, unknown email, or disabled account. Successful logins do not increment it.</p><p>The limit is enforced before any database lookup, so it also slows credential-stuffing attacks where the attacker does not know which emails are registered.</p><p>The window is in-memory and resets when the server restarts. There is no persistent block - the window is rolling.</p><h2 id="otp-issuance-limit" tabindex="-1">OTP - issuance limit <a class="header-anchor" href="#otp-issuance-limit" aria-label="Permalink to &quot;OTP - issuance limit&quot;">​</a></h2><p>To prevent OTP spam and mail server abuse, each user can request at most 3 new OTP codes within a 10-minute window.</p><table tabindex="0"><thead><tr><th>Limit</th><th>Window</th><th>Action on breach</th></tr></thead><tbody><tr><td>3 OTP requests per user</td><td>10 minutes</td><td>Error returned; no code is generated or sent</td></tr></tbody></table><h2 id="otp-and-totp-verification-lockout" tabindex="-1">OTP and TOTP - verification lockout <a class="header-anchor" href="#otp-and-totp-verification-lockout" aria-label="Permalink to &quot;OTP and TOTP - verification lockout&quot;">​</a></h2><p>After too many wrong codes are submitted, the account is temporarily locked.</p><table tabindex="0"><thead><tr><th>Limit</th><th>Window</th><th>Lockout duration</th></tr></thead><tbody><tr><td>5 failed OTP attempts</td><td>10 minutes (sliding)</td><td>10 minutes</td></tr><tr><td>5 failed TOTP attempts</td><td>10 minutes (sliding)</td><td>10 minutes</td></tr></tbody></table><p>The window is sliding: it resets when 10 minutes have passed since the first failed attempt in the current window. Lockout state is stored in the database and survives server restarts.</p><p>During lockout, even a correct code is rejected. This is intentional - it prevents an attacker from succeeding on the 6th attempt by simply waiting for the right code.</p><h2 id="password-reset-rate-limit" tabindex="-1">Password reset - rate limit <a class="header-anchor" href="#password-reset-rate-limit" aria-label="Permalink to &quot;Password reset - rate limit&quot;">​</a></h2><p>Password reset emails are rate-limited to prevent abuse of the mail sender.</p><table tabindex="0"><thead><tr><th>Limit</th><th>Scope</th><th>Window</th></tr></thead><tbody><tr><td>3 reset emails</td><td>Per email address</td><td>1 hour</td></tr><tr><td>10 reset emails</td><td>Per IP address</td><td>1 hour</td></tr></tbody></table><p>When the limit is hit, the endpoint still responds as if an email was sent - it just silently drops the request. This prevents confirming whether an address is registered.</p><h2 id="what-is-not-rate-limited" tabindex="-1">What is not rate limited <a class="header-anchor" href="#what-is-not-rate-limited" aria-label="Permalink to &quot;What is not rate limited&quot;">​</a></h2><ul><li>Password change (already requires the current password, TOTP if enrolled, and an active session)</li><li>Passkey registration (requires an active session)</li><li>Admin login (protected by the same argon2id hashing cost; consider deploying admin behind an IP allowlist)</li></ul>',21)])])}const u=e(r,[["render",n]]);export{p as __pageData,u as default};
